export function initTheme(button){button.addEventListener('click',()=>{document.documentElement.classList.toggle('dark');localStorage.setItem('csv-theme',document.documentElement.classList.contains('dark')?'dark':'light')})}
export function initCursorGlow(glow){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;let tx=innerWidth*.5,ty=innerHeight*.35,x=tx,y=ty;addEventListener('pointermove',e=>{tx=e.clientX;ty=e.clientY},{passive:true});const animate=()=>{x+=(tx-x)*.09;y+=(ty-y)*.09;glow.style.setProperty('--mouse-x',`${x}px`);glow.style.setProperty('--mouse-y',`${y}px`);requestAnimationFrame(animate)};requestAnimationFrame(animate)}
